import boto3
import json
import os
from typing import Dict, Any, List

def extract_and_normalize_expense(file_path: str) -> Dict[str, Any]:
    """
    Extracts expense data from a document using Amazon Textract and normalizes it
    into a standard JSON schema.

    This function requires AWS credentials (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY)
    and a region (AWS_REGION) to be configured in the environment.

    Args:
        file_path: The local path to the expense document (e.g., receipt, invoice).

    Returns:
        A dictionary containing the normalized expense data.
    """
    # Provider-identifying signal: boto3 client for AWS Textract
    textract_client = boto3.client("textract")

    with open(file_path, "rb") as document_file:
        document_bytes = document_file.read()

    # Provider-identifying signal: analyze_expense API call
    response = textract_client.analyze_expense(Document={"Bytes": document_bytes})

    normalized_data = {
        "vendor_name": None,
        "vendor_address": None,
        "invoice_date": None,
        "invoice_id": None,
        "total_amount": None,
        "tax_amount": None,
        "line_items": [],
    }

    if not response.get("ExpenseDocuments"):
        return normalized_data

    # Process the first document found
    expense_doc = response["ExpenseDocuments"][0]

    # Map summary fields from Textract response to our schema
    summary_fields = {
        field.get("Type", {}).get("Text"): field.get("ValueDetection", {}).get("Text")
        for field in expense_doc.get("SummaryFields", [])
    }

    normalized_data["vendor_name"] = summary_fields.get("VENDOR_NAME")
    normalized_data["vendor_address"] = summary_fields.get("VENDOR_ADDRESS")
    normalized_data["invoice_date"] = summary_fields.get("INVOICE_RECEIPT_DATE")
    normalized_data["invoice_id"] = summary_fields.get("INVOICE_RECEIPT_ID")

    # Clean and convert numeric fields
    total_str = summary_fields.get("TOTAL")
    if total_str:
        try:
            normalized_data["total_amount"] = float(total_str.replace("$", "").replace(",", "").strip())
        except (ValueError, TypeError):
            normalized_data["total_amount"] = total_str # Fallback to string if conversion fails

    tax_str = summary_fields.get("TAX")
    if tax_str:
        try:
            normalized_data["tax_amount"] = float(tax_str.replace("$", "").replace(",", "").strip())
        except (ValueError, TypeError):
            normalized_data["tax_amount"] = tax_str

    # Map line items
    line_items_list: List[Dict[str, Any]] = []
    for group in expense_doc.get("LineItemGroups", []):
        for line_item in group.get("LineItems", []):
            item_details = {}
            for field in line_item.get("LineItemExpenseFields", []):
                field_type = field.get("Type", {}).get("Text")
                field_value = field.get("ValueDetection", {}).get("Text")
                if not (field_type and field_value):
                    continue

                # Normalize line item field names and values
                if field_type == "ITEM":
                    item_details["description"] = field_value
                elif field_type == "QUANTITY":
                    try:
                        item_details["quantity"] = int(field_value)
                    except (ValueError, TypeError):
                        item_details["quantity"] = field_value
                elif field_type == "UNIT_PRICE":
                    try:
                        item_details["unit_price"] = float(field_value.replace("$", "").replace(",", "").strip())
                    except (ValueError, TypeError):
                        item_details["unit_price"] = field_value
                elif field_type == "PRICE":  # This is the total price for the line item
                    try:
                        item_details["total_price"] = float(field_value.replace("$", "").replace(",", "").strip())
                    except (ValueError, TypeError):
                        item_details["total_price"] = field_value

            if item_details:
                line_items_list.append(item_details)

    normalized_data["line_items"] = line_items_list

    return normalized_data
